import pandas as pd
import numpy as np
from pyspark.sql.functions import pandas_udf, col
from pyspark.sql.types import DoubleType

sales = spark.createDataFrame(
    [("A", 2.0), ("A", 8.0), ("B", 3.0), ("B", 12.0), ("B", 27.0)],
    ["grp", "value"],
)

# Series-to-scalar: input Series -> single scalar per group
@pandas_udf(DoubleType())
def geo_mean(v: pd.Series) -> float:
    return float(np.exp(np.log(v).mean()))

sales.groupBy("grp").agg(geo_mean(col("value")).alias("geo_mean")).show()
